#!/bin/bash

# SPDX-FileCopyrightText: 2024 The LineageOS Project
# SPDX-License-Identifier: Apache-2.0

# Generate Android.bp
echo "// DO NOT EDIT THIS FILE MANUALLY" > Android.bp

grep -o :\.\*override keys.mk | sort -u | while read -r key; do
    {
        echo ""
        echo "android_app_certificate {"
        echo "    name: \"${key:1}\","
        echo "    certificate: \"${key:1}\","
        echo "}"
    } >> Android.bp
done

# Generate keys
for key in ../../../build/make/target/product/security/*.pk8; do
    ./make_key.sh "$(basename "$key" .pk8)"
done

grep -o :\.\*override keys.mk | sort -u | while read -r key; do
    ./make_key.sh "${key:1}" 4096
done
